sys_variable_value.value:
(function executeAction(inputs, outputs) {

    var helper = new autoTrackImportOnDemand();

    var result = helper.importAndTransform(
        inputs.data_source_sys_id,
        inputs.transform_map_sys_id
    );

    if (!result) {
        gs.error('Run AutoTrack Import On Demand: importAndTransform returned null.');
        throw new Error('Import failed in autoTrackImportOnDemand');
    }

    // This must match the Script step output NAME: import_set_sys_id
    outputs.import_set_sys_id = result.import_set_sys_id;

})(inputs, outputs);

